# Step 1: List python source files to inspect core entry point
python3 - << 'PYEOF'
import os, fnmatch, json, sys
root = os.environ["TARGET_DIR"]
matches = []
for dirpath, dirnames, filenames in os.walk(os.path.join(root, "python")):
    for f in filenames:
        if f.endswith(".py"):
            matches.append(os.path.relpath(os.path.join(dirpath, f), root))
print("Python source files:")
for m in matches:
    print(m)
PYEOF

